89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public String getPostcode() {
105	        return this.postcode;
106	    }
107	
108	    public void setPostcode(String postcode) {
109	        this.postcode = postcode;
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public String getCustomerCode() {
121	        return this.customerCode;
122	    }
123	
124	    public void setCustomerCode(String customerCode) {
125	        this.customerCode = customerCode;
126	    }
127	
128	    public String getHouseholdId() {
129	        return this.householdId;
130	    }
131	
132	    public void setHouseholdId(String householdId) {
133	        this.householdId = householdId;
134	    }
135	
136	    public Integer getNamesakeCount() {
137	        return this.namesakeCount;
138	    }
139	
140	    public void setNamesakeCount(Integer namesakeCount) {
141	        this.namesakeCount = namesakeCount;
142	    }
143	
144	    /**
145	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
146	     */
147	    @Transient
148	    public String getDisplayName() {
149	        return this.getLastName() + ", " + this.getFirstName();
150	    }
151	
152	    /**
153	     * The owner's initials: the upper-cased first letters of the first and last name,
154	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
155	     */
156	    @Transient
157	    public String getInitials() {
158	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
159	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
160	    }
161	
162	    /**
163	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
164	     * the last two digits of the registration date year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
165	     * from the owner's own fields; {@code null} until both the customer code and registration date
166	     * are set.
167	     */
168	    @Transient
169	    public String getMembershipNumber() {
170	        if (this.customerCode == null || this.registrationDate == null) {
171	            return null;
172	        }
173	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
174	    }
175	
176	    /**
177	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
178	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
179	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
180	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
181	     */
182	    @Transient
183	    public Integer getCheckDigit() {
184	        if (this.customerCode == null) {
185	            return null;
186	        }
187	        int sum = 0;
188	        boolean dbl = true;
189	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
190	            char c = this.customerCode.charAt(i);
191	            if (c < '0' || c > '9') {
192	                continue;
193	            }
194	            int d = c - '0';
195	            if (dbl) {
196	                d *= 2;
197	                if (d > 9) {
198	                    d -= 9;
199	                }
200	            }
201	            sum += d;
202	            dbl = !dbl;
203	        }
204	        return (10 - (sum % 10)) % 10;
205	    }
206	
207	    /**
208	     * The owner's numeric membership level, from 1 to 3. It starts at 1, gains 1 when the owner has
209	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3
210	     * (level 4 is reserved for tenure). The inputs are the owner's own fields.
211	     */
212	    @Transient
213	    public Integer getMembershipLevel() {
214	        int level = 1;
215	        boolean hasEmail = this.email != null && !this.email.isBlank();
216	        if (hasEmail) {
217	            level++;
218	        }
219	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
220	        if (unique) {
221	            level++;
222	        }
223	        return Math.min(level, 3);
224	    }
225	
226	    /**
227	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
228	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
229	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
230	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
231	     */
232	    @Transient
233	    public String getLocality() {
234	        if (this.customerCode == null) {
235	            return "UNKNOWN";
236	        }
237	        int dash = this.customerCode.indexOf('-');
238	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
239	    }
240	
241	    /**
242	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
243	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
244	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
245	     * owner has none), and the household id the stored shared identifier (empty when the owner is
246	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
247	     * are equal; because the telephone is part of the key, two members of the same household with
248	     * different telephones have different identity keys.
249	     */
250	    @Transient
251	    public String getIdentityKey() {
252	        String telephonePart = this.telephone == null ? "" : this.telephone;
253	        String emailPart = this.email == null ? "" : this.email;
254	        String householdPart = this.householdId == null ? "" : this.householdId;
255	        return telephonePart + "|" + emailPart + "|" + householdPart;
256	    }
257	
258	    /**
259	     * The owner's preferred contact channel, derived from the owner's own fields:
260	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
261	     */
262	    @Transient
263	    public String getContactPreference() {
264	        boolean hasEmail = this.email != null && !this.email.isBlank();
265	        return hasEmail ? "EMAIL" : "PHONE";
266	    }
267	
268	    protected Set<Pet> getPetsInternal() {
269	        if (this.pets == null) {
270	            this.pets = new HashSet<>();
271	        }
272	        return this.pets;
273	    }
274	
275	    protected void setPetsInternal(Set<Pet> pets) {
276	        this.pets = pets;
277	    }
278	
279	    public List<Pet> getPets() {
280	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
281	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
282	        return Collections.unmodifiableList(sortedPets);
283	    }
284	
285	    public void setPets(List<Pet> pets) {
286	        this.pets = new HashSet<>(pets);
287	    }
288	
289	    public void addPet(Pet pet) {
290	        getPetsInternal().add(pet);
291	        pet.setOwner(this);
292	    }
293	
294	    /**
295	     * Return the Pet with the given name, or null if none found for this Owner.
296	     *
297	     * @param name to test
298	     * @return true if pet name is already in use
299	     */
300	    public Pet getPet(String name) {
301	        return getPet(name, false);
302	    }
303	
304	    /**
305	     * Return the Pet with the given name, or null if none found for this Owner.
306	     *
307	     * @param name to test
308	     * @return true if pet name is already in use
309	     */
310	    public Pet getPet(String name, boolean ignoreNew) {
311	        name = name.toLowerCase();
312	        for (Pet pet : getPetsInternal()) {
313	            if (!ignoreNew || !pet.isNew()) {
314	                String compName = pet.getName();
315	                compName = compName.toLowerCase();
316	                if (compName.equals(name)) {
317	                    return pet;
318	                }
319	            }
320	        }
321	        return null;
322	    }
323	
324	    public Pet getPet(Integer petId) {
