65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
74	     * domain containing at least one dot, with no whitespace in any part.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
80	     * new owner's id, customer code and registration date.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys are the
86	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
87	     * expanded form it is replaced with.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
93	
94	    /**
95	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
96	     * is at capacity and cannot take any more.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * The maximum number of owners that may be registered in a single day. Once this many owners
102	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
103	     * owners can be created that day.
104	     */
105	    private static final int DAILY_OWNER_LIMIT = 100;
106	
107	    /**
108	     * The number of owners that may be registered on a single business day before a response starts
109	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
110	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
111	     * high volume.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    /**
116	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
117	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
118	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
119	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
120	     */
121	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
122	        "61", 9,
123	        "1", 10);
124	
125	    /**
126	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
127	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
128	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
129	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
130	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
131	     */
132	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
133	        "NSW", new int[] {2000, 2099},
134	        "VIC", new int[] {3000, 3099},
135	        "QLD", new int[] {4000, 4099});
136	
137	    /**
138	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
139	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
140	     * any 4-digit postcode.
141	     */
142	    private static final Map<String, String> CITY_REGION = Map.of(
143	        "Sydney", "NSW",
144	        "Melbourne", "VIC",
145	        "Brisbane", "QLD");
146	
147	    private final ClinicService clinicService;
148	
149	    private final OwnerMapper ownerMapper;
150	
151	    private final PetMapper petMapper;
152	
153	    private final VisitMapper visitMapper;
154	
155	    public OwnerRestControllerV1(ClinicService clinicService,
156	                                 OwnerMapper ownerMapper,
157	                                 PetMapper petMapper,
158	                                 VisitMapper visitMapper) {
159	        this.clinicService = clinicService;
160	        this.ownerMapper = ownerMapper;
161	        this.petMapper = petMapper;
162	        this.visitMapper = visitMapper;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
168	        Collection<Owner> owners;
169	        if (lastName != null) {
170	            owners = this.clinicService.findOwnerByLastName(lastName);
171	        } else {
172	            owners = this.clinicService.findAllOwners();
173	        }
174	        if (owners.isEmpty()) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        applyBulkSignupWarning(ownerDto);
189	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
195	        validateRequiredFields(ownerFieldsDto);
196	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
197	        LocalDate registrationDate = toBusinessDay(
198	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
199	        rejectDailyLimitReached(registrationDate);
200	        HttpHeaders headers = new HttpHeaders();
201	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
202	        String address = normalizeAddress(ownerFieldsDto.getAddress());
203	        owner.setAddress(address);
204	        rejectCityAtCapacity(owner.getCity());
205	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
206	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
207	        }
208	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
209	        owner.setTelephone(telephone);
210	        String email = normalizeEmail(ownerFieldsDto.getEmail());
211	        owner.setEmail(email);
212	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
213	        rejectDuplicateIdentity(owner);
214	        owner.setRegistrationDate(registrationDate);
215	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
216	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
217	        this.clinicService.saveOwner(owner);
218	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
219	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
220	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
221	        applyBulkSignupWarning(ownerDto);
222	        headers.setLocation(UriComponentsBuilder.newInstance()
223	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
224	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
230	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
231	        if (currentOwner == null) {
232	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	        }
234	        currentOwner.setAddress(ownerFieldsDto.getAddress());
235	        currentOwner.setCity(ownerFieldsDto.getCity());
236	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
237	        currentOwner.setLastName(ownerFieldsDto.getLastName());
238	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
239	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
240	        this.clinicService.saveOwner(currentOwner);
241	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Transactional
246	    @Override
247	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        this.clinicService.deleteOwner(owner);
253	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        HttpHeaders headers = new HttpHeaders();
264	        Pet pet = petMapper.toPet(petFieldsDto);
265	        owner.setId(ownerId);
266	        pet.setOwner(owner);
267	        pet.getType().setName(null);
268	        this.clinicService.savePet(pet);
269	        PetDto petDto = petMapper.toPetDto(pet);
270	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
271	            .buildAndExpand(pet.getId()).toUri());
272	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
273	    }
274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
278	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
279	        if (currentOwner != null) {
280	            Pet currentPet = this.clinicService.findPetById(petId);
281	            if (currentPet != null) {
282	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
283	                currentPet.setName(petFieldsDto.getName());
284	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
285	                this.clinicService.savePet(currentPet);
286	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	            }
288	        }
289	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
295	        HttpHeaders headers = new HttpHeaders();
296	        Visit visit = visitMapper.toVisit(visitFieldsDto);
297	        Pet pet = new Pet();
298	        pet.setId(petId);
299	        visit.setPet(pet);
300	        this.clinicService.saveVisit(visit);
301	        VisitDto visitDto = visitMapper.toVisitDto(visit);
