383	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
384	     *                                     out of range for the city's region, yielding a 400 response
385	     */
386	    private String validatePostcode(String postcode, String region) {
387	        if (postcode == null) {
388	            return null;
389	        }
390	        if (!postcode.matches("[0-9]{4}")) {
391	            throw new InvalidOwnerFieldsException(List.of("postcode"));
392	        }
393	        int[] range = REGION_POSTCODES.get(region);
394	        if (range != null) {
