403	    /**
404	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
405	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
406	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
407	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
408	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
409	     *
410	     * @param telephone the raw telephone value submitted by the client
411	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
412	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
413	     *                                     400 response
414	     */
415	    private String normalizeTelephone(String telephone) {
416	        String e164 = toE164(telephone);
417	        if (e164 == null) {
418	            throw new InvalidOwnerFieldsException(List.of("telephone"));
419	        }
420	        return e164;
421	    }
422	
423	    /**
424	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
425	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
426	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
427	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
428	     * and when the supplied country code is one with a known national-number length
429	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
430	     * number must have exactly that many digits.
431	     *
432	     * @param telephone the raw telephone value, possibly {@code null}
433	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
434	     */
435	    private String toE164(String telephone) {
436	        if (telephone == null) {
437	            return null;
438	        }
439	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
440	        boolean hasPlus = cleaned.startsWith("+");
441	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
442	        String nationalSignificant = hasPlus
443	            ? digits
444	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
445	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
446	            return null;
447	        }
448	        if (!hasValidNationalNumberLength(nationalSignificant)) {
449	            return null;
450	        }
451	        return "+" + nationalSignificant;
452	    }
453	
454	    /**
455	     * Checks the national-number length of an E.164 number (country code plus national significant
456	     * digits, no leading {@code '+'}) against the per-country requirement in
457	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
458	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
459	     * country code is not listed carries no per-country length requirement and is accepted.
460	     *
461	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
462	     *                            leading {@code '+'}
463	     * @return {@code true} if the national-number length is correct for the country code, or the
464	     *         country code has no listed requirement; {@code false} otherwise
465	     */
466	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
467	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
468	            .filter(nationalSignificant::startsWith)
469	            .max(Comparator.comparingInt(String::length))
470	            .orElse(null);
471	        if (countryCode == null) {
472	            return true;
473	        }
474	        int nationalLength = nationalSignificant.length() - countryCode.length();
475	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
476	    }
