517	    /**
518	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
519	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
520	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
521	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
522	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
523	     * same postcode region, telephone and last name always yield the same customer code.
524	     *
525	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
526	     * @param telephone the owner's normalized (E.164) telephone
527	     * @param lastName  the owner's last name
528	     * @return the formatted customer code
529	     */
530	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
531	        String region = regionForPostcode(postcode);
532	        String hash8 = hash8(telephone + lastName);
533	        return region + "-" + hash8;
534	    }
