536	    /**
537	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
538	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
539	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
540	     * {@code <REGION>} segment baked into the {@code customerCode}.
541	     *
542	     * @param postcode the owner's postcode, or {@code null}
543	     * @return the region code, or {@code 'UNKNOWN'}
544	     */
545	    private String regionForPostcode(String postcode) {
546	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
547	            return "UNKNOWN";
548	        }
549	        int value = Integer.parseInt(postcode);
550	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
551	            int[] range = entry.getValue();
552	            if (value >= range[0] && value <= range[1]) {
553	                return entry.getKey();
554	            }
555	        }
556	        return "UNKNOWN";
557	    }
