559	    /**
560	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
561	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
562	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
563	     * region.
564	     *
565	     * @param city the owner's city
566	     * @return the region code, or {@code 'UNKNOWN'}
567	     */
568	    private String regionForCity(String city) {
569	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
570	    }
