572	    /**
573	     * Returns the first eight upper-cased hex characters of the SHA-256 digest of the given input,
574	     * used as the {@code <HASH8>} segment of a {@code customerCode}.
575	     *
576	     * @param input the value to hash
577	     * @return the first eight upper-cased hex characters of its SHA-256 digest
578	     */
579	    private String hash8(String input) {
580	        try {
581	            byte[] digest = MessageDigest.getInstance("SHA-256")
582	                .digest(input.getBytes(StandardCharsets.UTF_8));
583	            StringBuilder hex = new StringBuilder(digest.length * 2);
584	            for (byte b : digest) {
585	                hex.append(String.format("%02x", b));
586	            }
587	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
588	        } catch (NoSuchAlgorithmException e) {
589	            throw new IllegalStateException("SHA-256 algorithm not available", e);
590	        }
591	    }
