642	    /**
643	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
644	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
645	     *
646	     * @param registrationDate the business day to count owners for
647	     * @return the number of existing owners registered on that day
648	     */
649	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
