668	    /**
669	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
670	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
671	     * applies to the effective registration date whether it was supplied in the request or defaulted
672	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
673	     * feeds every value derived from it (such as the membership number's year segment and the daily
674	     * create-limit's per-day bucket).
675	     *
676	     * @param date the effective registration date, supplied or defaulted
677	     * @return the same date when it is a weekday, otherwise the next Monday
678	     */
679	    private LocalDate toBusinessDay(LocalDate date) {
680	        LocalDate adjusted = date;
681	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
682	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
683	            adjusted = adjusted.plusDays(1);
684	        }
685	        return adjusted;
686	    }
