688	    /**
689	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
690	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
691	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
692	     * separate telephone, email and household checks are all expressed through it. Because the
693	     * telephone is part of the key, two members of the same household (same {@code householdId})
694	     * with different telephones have different identity keys and are both allowed; only a whole-key
695	     * match is a duplicate. The owner being created already carries its normalized telephone,
696	     * email and (if any) household id, and existing owners store the same normalized forms, so the
697	     * keys are compared directly.
698	     *
699	     * @param owner the owner being created, with its telephone, email and household id already set
700	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
701	     *                                         yielding a 409 Conflict response
702	     */
703	    private void rejectDuplicateIdentity(Owner owner) {
704	        String identityKey = owner.getIdentityKey();
705	        boolean inUse = this.clinicService.findAllOwners().stream()
706	            .map(Owner::getIdentityKey)
707	            .anyMatch(identityKey::equals);
708	        if (inUse) {
709	            throw new DuplicateOwnerIdentityException(identityKey);
710	        }
711	    }
