713	    /**
714	     * Finds every existing owner belonging to the household identified by the given last name and
715	     * address — that is, the owners the {@code sharesHousehold} opt-in joins. Both the last name and
716	     * the address are compared case-insensitively with surrounding and internal whitespace collapsed,
717	     * so values that differ only in letter case or spacing still match. This definition of household
718	     * membership is used by {@link #assignHousehold}.
719	     *
720	     * @param lastName the last name of the owner being created
721	     * @param address  the address of the owner being created
722	     * @return the existing owners in that household, or an empty list if there are none
723	     */
724	    private List<Owner> findHouseholdMembers(String lastName, String address) {
725	        String normalizedLastName = normalizeForComparison(lastName);
726	        String normalizedAddress = normalizeAddress(address);
727	        return this.clinicService.findAllOwners().stream()
728	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
729	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
730	            .toList();
731	    }
