733	    /**
734	     * Enrolls a newly created owner into the household of any existing owner that shares its last
735	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
736	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
737	     * whitespace. When at least one such owner already exists, every member of the household — the
738	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
739	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
740	     * and address is created and back-filled onto the existing members. When no owner yet lives at
741	     * that address under the same last name no identifier is assigned and the owner is created alone.
742	     *
743	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
744	     * @param lastName the last name of the owner being created
745	     * @param address  the address of the owner being created
746	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
747	     */
748	    private String assignHousehold(Owner newOwner, String lastName, String address) {
749	        List<Owner> members = findHouseholdMembers(lastName, address);
750	        if (members.isEmpty()) {
751	            return null;
752	        }
753	        String householdId = members.stream()
754	            .map(Owner::getHouseholdId)
755	            .filter(existing -> existing != null && !existing.isBlank())
756	            .findFirst()
757	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
758	        for (Owner member : members) {
759	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
760	                member.setHouseholdId(householdId);
761	                this.clinicService.saveOwner(member);
762	            }
763	        }
764	        newOwner.setHouseholdId(householdId);
765	        return householdId;
766	    }
