768	    /**
769	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
770	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
771	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
772	     * same identifier, so members of one household share a single value.
773	     *
774	     * @param normalizedLastName the household's last name, already normalized for comparison
775	     * @param normalizedAddress  the household's address, already normalized for comparison
776	     * @return the derived household identifier
777	     */
778	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
779	        try {
780	            byte[] digest = MessageDigest.getInstance("SHA-256")
781	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
782	            StringBuilder hex = new StringBuilder(digest.length * 2);
783	            for (byte b : digest) {
784	                hex.append(String.format("%02x", b));
785	            }
786	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
787	        } catch (NoSuchAlgorithmException e) {
788	            throw new IllegalStateException("SHA-256 algorithm not available", e);
789	        }
790	    }
