792	    /**
793	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
794	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
795	     * the result is lower-cased.
796	     *
797	     * @param value the value to normalize, possibly {@code null}
798	     * @return the normalized value, or an empty string if {@code value} is {@code null}
799	     */
800	    private String normalizeForComparison(String value) {
801	        if (value == null) {
802	            return "";
803	        }
804	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
805	    }
