807	    /**
808	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
809	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
810	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
811	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
812	     * This normalized value is what gets stored and returned, and it is the form every address
813	     * comparison (household duplicate detection and the shared household id) uses.
814	     *
815	     * @param address the raw address value submitted by the client, possibly {@code null}
816	     * @return the normalized address, or an empty string if {@code address} is {@code null}
817	     */
818	    private String normalizeAddress(String address) {
819	        if (address == null) {
820	            return "";
821	        }
822	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
823	        if (collapsed.isEmpty()) {
824	            return collapsed;
825	        }
826	        String[] tokens = collapsed.split(" ");
827	        StringBuilder normalized = new StringBuilder(collapsed.length());
828	        for (int i = 0; i < tokens.length; i++) {
829	            if (i > 0) {
830	                normalized.append(' ');
831	            }
832	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
833	        }
834	        return normalized.toString();
835	    }
836	}
